python3 - <<'PY'
import os
from pathlib import Path
root = Path('/work/journal/notes')
try:
    counts = []
    with os.scandir(root) as entries:
        for entry in entries:
            if entry.is_file(follow_symlinks=False):
                with open(entry.path, 'rb') as f:
                    count = 0
                    last = b''
                    while chunk := f.read(65536):
                        count += chunk.count(b'\n')
                        last = chunk[-1:]
                    if last and last != b'\n':
                        count += 1
                counts.append((entry.name, count))
    if not counts:
        print('notes 目录中没有直属普通文件。')
    else:
        highest = max(count for _, count in counts)
        for name, count in sorted(counts):
            if count == highest:
                print(f'notes/{name}\t{count} 行')
except OSError as exc:
    print(f'统计失败：{exc}')
    raise SystemExit(1)
PY

